sp_widget.css:
.metrics-grid{

display:grid;

grid-template-columns:
repeat(4,1fr);

gap:22px;

}


.metric-card{

background:#FFFFFF;

height:190px;

border-radius:28px;

padding:26px;

position:relative;

overflow:hidden;

box-shadow:
0 14px 40px rgba(0,0,0,.06);

display:flex;

flex-direction:column;

justify-content:center;

cursor:pointer;

transition:.25s;

}


.metric-card:hover{

transform:
translateY(-5px);

}


.top{

display:flex;

align-items:center;

gap:24px;

position:relative;

z-index:2;

}



.metric-icon{

width:78px;

height:78px;

min-width:78px;

border-radius:22px;

display:flex;

align-items:center;

justify-content:center;

font-size:34px;

}



.metric-value{

font-size:62px;

font-weight:900;

color:#07195A;

line-height:1;

}



.metric-title{

font-size:22px;

font-weight:800;

color:#6D7CA7;

}



.metric-sub{

margin-left:102px;

margin-top:6px;

font-size:14px;

color:#9AA5C2;

position:relative;

z-index:2;

}



.bg-circle{

position:absolute;

right:-55px;

bottom:-55px;

width:170px;

height:170px;

border-radius:50%;

opacity:.08;

}



/* THEMES */

.employees{

border-left:5px solid #2F62F5;

}

.employees .metric-icon{

background:#2F62F5;

color:white;

}

.employees .bg-circle{

background:#2F62F5;

}



.department{

border-left:5px solid #08B77B;

}

.department .metric-icon{

background:#DCF8EA;

}

.department .bg-circle{

background:#00B87A;

}



.active{

border-left:5px solid #FDB022;

}

.active .metric-icon{

background:#FFF2D8;

}

.active .bg-circle{

background:#FFB020;

}



.inactive{

border-left:5px solid #A259FF;

}

.inactive .metric-icon{

background:#F2E8FF;

}

.inactive .bg-circle{

background:#A259FF;

}



/* RESPONSIVE */

@media(max-width:1200px){

.metrics-grid{

grid-template-columns:
1fr 1fr;

}

}


@media(max-width:700px){

.metrics-grid{

grid-template-columns:
1fr;

}

}

sp_widget.script:
(function(){

data.cards=[];

var EMP=
'x_1902481_employ_0_employee';

var DEPT=
'x_1902481_employ_0_department';



function count(table,field,value){

var ga=
new GlideAggregate(table);

if(field)
ga.addQuery(field,value);

ga.addAggregate('COUNT');

ga.query();

if(ga.next())
return parseInt(
ga.getAggregate('COUNT'),
10
);

return 0;

}



data.cards=[

{

title:'Employees',

sub:'All employees',

value:
count(EMP),

icon:'👥',

class:'employees',

route:
'/ev?id=employee_directory'

},

{

title:'Departments',

sub:'Across organization',

value:
count(DEPT),

icon:'🏢',

class:'department',

route:
'/ev?id=department'

},

{

title:'Active Employees',

sub:'Currently working',

value:
count(
EMP,
'status',
'active'
),

icon:'🟢',

class:'active',

route:
'/ev?id=employee_directory&status=active'

},

{

title:'Inactive Employees',

sub:'Need attention',

value:
count(
EMP,
'status',
'inactive'
),

icon:'🔴',

class:'inactive',

route:
'/ev?id=employee_directory&status=inactive'

}

];

})();
